<?php
function watchysLotGateProbe(PDO $db,$sourcePrefix,array $connection,callable $progress,callable $record)
{
 require_once __DIR__.'/module/classes/WatchysNativeSchema.php';require_once __DIR__.'/module/classes/WatchysStockSchema.php';require_once __DIR__.'/module/classes/WatchysStockAllocator.php';require_once __DIR__.'/module/classes/WatchysStockWriteGate.php';
 $p='wcfg_lot_probe_'.bin2hex(random_bytes(6)).'_';$token=bin2hex(random_bytes(32));$created=[];$triggers=[];$record($p,$created,$triggers);
 $ddl=['stock_available'=>'CREATE TABLE `'.$p.'stock_available` LIKE `'.$sourcePrefix.'stock_available`']+WatchysNativeSchema::definitions($p)+WatchysStockSchema::definitions($p)+['probe_owner'=>'CREATE TABLE `'.$p.'probe_owner` (token CHAR(64) PRIMARY KEY) ENGINE=InnoDB'];
 try{
  foreach($ddl as $name=>$sql){$db->exec($sql);$created[]=$name;$record($p,$created,$triggers);}
  $s=$db->prepare('INSERT INTO `'.$p.'probe_owner` VALUES(?)');$s->execute([$token]);$db->exec('INSERT INTO `'.$p.'stock_available` SELECT * FROM `'.$sourcePrefix.'stock_available` WHERE id_product=7736 AND id_product_attribute=0 AND id_shop=1 AND id_shop_group=0');if((int)$db->query('SELECT COUNT(*) FROM `'.$p.'stock_available`')->fetchColumn()!==1){throw new RuntimeException('Fixture stock absente.');}
  $db->exec('UPDATE `'.$p.'stock_available` SET quantity=2,reserved_quantity=0,physical_quantity=2,depends_on_stock=0');$stock=(int)$db->query('SELECT id_stock_available FROM `'.$p.'stock_available`')->fetchColumn();$db->exec('INSERT INTO `'.$p.'watchys_stock_component` VALUES(7736,0,1,1)');
  foreach(WatchysNativeSchema::triggers($p) as $name=>$sql){$db->exec($sql);$triggers[]=$name;$record($p,$created,$triggers);}
  $worker=static function($action,$expected)use($p,$token,$connection){$cfg=$connection+['prefix'=>$p,'token'=>$token,'action'=>$action];$r=WatchysNativeLotFiles::process([PHP_BINARY,__DIR__.'/gate-worker.php'],__DIR__,json_encode($cfg,JSON_THROW_ON_ERROR)."\n",15);if($r['exit']!==0||trim($r['out'])!==$expected){throw new RuntimeException('Garde MySQL non confirmée : '.$action.' / '.trim($r['out']));}};
  $cid=(int)$db->query('SELECT CONNECTION_ID()')->fetchColumn();$nonce=bin2hex(random_bytes(16));$s=$db->prepare('INSERT INTO `'.$p.'watchys_stock_permit` VALUES(?,?,?,?,?,?,?,?,?)');$s->execute([$cid,$stock,$nonce,2,0,2,1,1,2]);$worker('raw','DENIED');$db->exec('DELETE FROM `'.$p.'watchys_stock_permit`');$progress('Garde MySQL : une autre connexion ne peut pas utiliser le permis du propriétaire.');
  $db->exec('UPDATE `'.$p.'watchys_stock_component` SET enabled=0');$db->exec('UPDATE `'.$p.'stock_available` SET quantity=1,reserved_quantity=0,physical_quantity=1');$db->exec('UPDATE `'.$p.'watchys_stock_component` SET enabled=1');
  $db->beginTransaction();$req=[['identity'=>['id_order_detail'=>100,'component_product_id'=>7736,'component_attribute_id'=>0,'id_order'=>100,'id_customization'=>100,'id_shop'=>1],'required_units'=>1,'nomenclature_hash'=>hash('sha256','gate-owner')]];(new WatchysStockAllocator($db,$p,new WatchysStockWriteGate($db,$p)))->apply($req,'owner',['kind'=>'status','status_id'=>10]);$worker('allocate','BLOCKED');$db->commit();$worker('allocate','REFUSED');
  if((int)$db->query('SELECT COUNT(*) FROM `'.$p.'watchys_order_component`')->fetchColumn()!==1||(int)$db->query('SELECT COUNT(*) FROM `'.$p.'watchys_stock_permit`')->fetchColumn()!==0){throw new RuntimeException('Double allocation ou permis résiduel.');}$progress('Dernière pièce avec garde SQL : second allocateur bloqué puis refusé, sans permis résiduel.');
 }finally{if($db->inTransaction()){$db->rollBack();}foreach(array_reverse($triggers) as $name){$db->exec('DROP TRIGGER `'.$name.'`');}foreach(array_reverse($created) as $name){$db->exec('DROP TABLE `'.$p.$name.'`');}$record($p,[],[]);}
}
